/// <summary>
/// Every failure, with a stable machine code (see `docs/group-e2ee.md`).
/// </summary>
public class GroupCryptoException: UniffiException {
    GroupCryptoException() : base() {}
    GroupCryptoException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// Operation failed; `code` is stable, `message` is for logs.
    /// </summary>
    
    public class Failure : GroupCryptoException {
        // Members
        public string @code;
        public string @detail;

        // Constructor
        public Failure(
                string @code, 
                string @detail) : base(
                "@code" + "=" + @code+ ", " +
                "@detail" + "=" + @detail) {

            this.@code = @code;

            this.@detail = @detail;
        }
    }
    

    
}

class FfiConverterTypeGroupCryptoError : FfiConverterRustBuffer<GroupCryptoException>, CallStatusErrorHandler<GroupCryptoException> {
    public static FfiConverterTypeGroupCryptoError INSTANCE = new FfiConverterTypeGroupCryptoError();

    public override GroupCryptoException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new GroupCryptoException.Failure(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeGroupCryptoError.Read()", value));
        }
    }

    public override int AllocationSize(GroupCryptoException value) {
        switch (value) {

            case GroupCryptoException.Failure variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@code)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeGroupCryptoError.AllocationSize()", value));
        }
    }

    public override void Write(GroupCryptoException value, BigEndianStream stream) {
        switch (value) {
            case GroupCryptoException.Failure variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@code, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeGroupCryptoError.Write()", value));
        }
    }
}





