public record Incoming {
    
    public record Message (
        ReceivedMessage MessageValue
    ) : Incoming {}
    
    public record HistoryOffer (
        Pigeonpost.GroupCrypto.HistoryOffer Offer
    ) : Incoming {}
    
    public record Commit (
        CommitOutcome Outcome
    ) : Incoming {}
    
    public record OwnCommitConfirmed (
        CommitOutcome Outcome
    ) : Incoming {}
    
    public record Own: Incoming {}
    
    

    
}

class FfiConverterTypeIncoming : FfiConverterRustBuffer<Incoming>{
    public static FfiConverterRustBuffer<Incoming> INSTANCE = new FfiConverterTypeIncoming();

    public override Incoming Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new Incoming.Message(
                    FfiConverterTypeReceivedMessage.INSTANCE.Read(stream)
                );
            case 2:
                return new Incoming.HistoryOffer(
                    FfiConverterTypeHistoryOffer.INSTANCE.Read(stream)
                );
            case 3:
                return new Incoming.Commit(
                    FfiConverterTypeCommitOutcome.INSTANCE.Read(stream)
                );
            case 4:
                return new Incoming.OwnCommitConfirmed(
                    FfiConverterTypeCommitOutcome.INSTANCE.Read(stream)
                );
            case 5:
                return new Incoming.Own(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeIncoming.Read()", value));
        }
    }

    public override int AllocationSize(Incoming value) {
        switch (value) {
            case Incoming.Message variant_value:
                return 4
                    + FfiConverterTypeReceivedMessage.INSTANCE.AllocationSize(variant_value.MessageValue);
            case Incoming.HistoryOffer variant_value:
                return 4
                    + FfiConverterTypeHistoryOffer.INSTANCE.AllocationSize(variant_value.Offer);
            case Incoming.Commit variant_value:
                return 4
                    + FfiConverterTypeCommitOutcome.INSTANCE.AllocationSize(variant_value.Outcome);
            case Incoming.OwnCommitConfirmed variant_value:
                return 4
                    + FfiConverterTypeCommitOutcome.INSTANCE.AllocationSize(variant_value.Outcome);
            case Incoming.Own variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeIncoming.AllocationSize()", value));
        }
    }

    public override void Write(Incoming value, BigEndianStream stream) {
        switch (value) {
            case Incoming.Message variant_value:
                stream.WriteInt(1);
                FfiConverterTypeReceivedMessage.INSTANCE.Write(variant_value.MessageValue, stream);
                break;
            case Incoming.HistoryOffer variant_value:
                stream.WriteInt(2);
                FfiConverterTypeHistoryOffer.INSTANCE.Write(variant_value.Offer, stream);
                break;
            case Incoming.Commit variant_value:
                stream.WriteInt(3);
                FfiConverterTypeCommitOutcome.INSTANCE.Write(variant_value.Outcome, stream);
                break;
            case Incoming.OwnCommitConfirmed variant_value:
                stream.WriteInt(4);
                FfiConverterTypeCommitOutcome.INSTANCE.Write(variant_value.Outcome, stream);
                break;
            case Incoming.Own variant_value:
                stream.WriteInt(5);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeIncoming.Write()", value));
        }
    }
}






class FfiConverterOptionalByteArray: FfiConverterRustBuffer<byte[]?> {
    public static FfiConverterOptionalByteArray INSTANCE = new FfiConverterOptionalByteArray();

    public override byte[]? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterByteArray.INSTANCE.Read(stream);
    }

    public override int AllocationSize(byte[]? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterByteArray.INSTANCE.AllocationSize((byte[])value);
        }
    }

    public override void Write(byte[]? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterByteArray.INSTANCE.Write((byte[])value, stream);
        }
    }
}




class FfiConverterSequenceString: FfiConverterRustBuffer<string[]> {
    public static FfiConverterSequenceString INSTANCE = new FfiConverterSequenceString();

    public override string[]  Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        if (length == 0) {
            return [];
        }

        var result = new string[length];
        var readFn = FfiConverterString.INSTANCE.Read;
        for (int i = 0; i < length; i++) {
            result[i] = readFn(stream);
        }
        return result;
    }

    public override int AllocationSize(string[]  value) {
        var sizeForLength = 4;

        // details/1-empty-list-as-default-method-parameter.md
        if (value == null) {
            return sizeForLength;
        }

        var allocationSizeFn = FfiConverterString.INSTANCE.AllocationSize;
        var sizeForItems = value.Sum(item => allocationSizeFn(item));
        return sizeForLength + sizeForItems;
    }

    public override void Write(string[] value, BigEndianStream stream) {
        // details/1-empty-list-as-default-method-parameter.md
        if (value == null) {
            stream.WriteInt(0);
            return;
        }

        stream.WriteInt(value.Length);
        var writerFn = FfiConverterString.INSTANCE.Write;
        value.ForEach(item => writerFn(item, stream));
    }
}




